from datetime import datetime, timezone, timedelta

def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    seconds = nanoseconds // 1_000_000_000
    microseconds = (nanoseconds % 1_000_000_000) // 1_000
    if tz is None:
        return datetime.fromtimestamp(seconds, tz=timezone.utc) + timedelta(microseconds=microseconds)
    else:
        return datetime.fromtimestamp(seconds, tz=tz) + timedelta(microseconds=microseconds)
