def _inline_r_setup(code: str) -> str:
    """
    Some behaviour of R cannot be configured via env variables, but can
    only be configured via R options once R has started. These are set here.
    """
    # Assuming we need to inject R options into the code
    r_options = {
        "R_DEFAULT_COUNTRY": "US",
        "R_DEFAULT_SCALE_DIGITS": "4"
    }

    setup_code = "\n".join([f"options({key} = {value})" for key, value in r_options.items()])
    return "\n".join([code, setup_code])

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    # Create a list from the input sequence to avoid modifying the original
    seq = list(seq)
    # Use random.sample to deterministically shuffle the list
    return random.sample(seq, len(seq))

