@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    def format_tb(tb, level):
        if not tb or level <= 0:
            return ''
        frame = tb.tb_frame
        return f"File \"{frame.f_code.co_filename}\", line {frame.f_lineno}, in {frame.f_code.co_name}\n    {frame.f_code.co_code.decode().split('\\n')[frame.f_lineno - 1]}\n" + format_tb(tb.tb_next, level - 1)

    def format_exc_info(exc_info, level):
        if not exc_info or level <= 0:
            return ''
        return f"{exc_info[0].__name__}: {exc_info[1]}\n" + format_tb(exc_info[2], level)

    return format_exc_info((None, e, sys.exc_info()[2]), max_level)
