    """
    Reduce a list of base classes to its ordered minimum equivalent
    """
    if not all(issubclass(cls, type) for cls in classes):
        raise TypeError("All elements in the input list must be base classes")

    new_classes = list(classes)
    while True:
        changed = False
        for i in range(len(new_classes)):
            for j in range(i + 1, len(new_classes)):
                if new_classes[i] is new_classes[j]:
