def _c_optimizations_available():
    """
    Return the C optimization module, if available, otherwise
    a false value.

    If the optimizations are required but not available, this
    raises the ImportError.

    This does not say whether they should be used or not.
    """
    try:
        spec = importlib.util.find_spec("pybind11")
        if spec is None:
            raise ImportError("pybind11 not found")
        return importlib.util.import_module("pybind11")
    except ImportError as e:
        raise ImportError("C optimizations not available:") from e

