def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    default_observer_schema = {}

    # Check if the application has a manifest
    if 'manifest' in app.spec and app.spec.manifest is not None:
        # Iterate over each resource in the manifest
        for resource in app.spec.manifest.get('resources', []):
            # Check if the resource has a custom observer schema
            if 'observer_schema' not in resource:
                # Generate a default observer schema for the resource
                default_observer = {
                    'type': 'object',
                    'properties': {}
                }
                # Add properties to the default observer schema based on resource type
                resource_type = resource.get('apiVersion', '') + '/' + resource.get('kind', '')
                if resource_type == 'v1/Pod':
                    default_observer['properties']['status'] = {'type': 'string'}
                elif resource_type == 'apps/v1/Deployment':
                    default_observer['properties']['spec'] = {
                        'type': 'object',
                        'properties': {
                            'replicas': {'type': 'integer'}
                        }
