def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os
    from collections import defaultdict

    try:
        data = defaultdict(list)
        for root, _, files in os.walk(folder):
            for file in files:
                if file.endswith('.xml'):
                    basename = os.path.splitext(file)[0]
                    data[basename].append(os.path.join(root, file))

        return dict(data)
    except Exception as e:
        print(f"Error exploring folder: {e}")
        return {}

def _eval_file(prefix, filename, file_folder):
    """
    Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    filename : str
        nome do arquivo completo
    file_folder : str
        caminho da pasta onde o arquivo está localizado

    Returns
    -------
    dict
    """
    if filename.endswith('.xml'):
        return {'type': 'asset', 'path': os.path.join(file_folder, filename)}
    elif filename.endswith('.mp4') or filename.endswith('.jpg'):
        return {'type': 'rendition', 'path': os.path.join(file_folder, filename)}
    else:
        return {'type': 'unknown', 'path': os.path.join(file_folder, filename)}

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    if not os.path.exists(zip_path):
        raise FileNotFoundError(f"The file {zip_path} does not exist.")

    try:
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            data_dict = {}
            for file_info in zip_ref.infolist():
                if file_info.filename.endswith('.xml'):
                    file_name = os.path.basename(file_info.filename)
                    if file_name not in data_dict:
                        data_dict[file_name] = {}
                    content = zip_ref.read(file_info.filename)
                    data_dict[file_name][file_name] = content.decode('utf-8')

            return data_dict
    except zipfile.BadZipFile:
        raise ValueError(f"The file {zip_path} is not a valid ZIP file.")

