def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """
    Call the given command(s).

    :param commands: The command(s) to run. Can be a single command or a list of commands.
    :param args: Arguments for the command(s).
    :param cwd: The current working directory to run the command(s) in.
    :param verbose: If True, print verbose output.
    :param hide_stderr: If True, hide the standard error.
    :param env: The environment to run the command(s) in.
    """
    import subprocess
    if not isinstance(commands, list):
        commands = [commands]
    for command in commands:
        try:
            if verbose:
                print(f"Running command: {command} with args: {args}")
            if hide_stderr:
                output = subprocess.check_output([command] + args, cwd=cwd, stderr=subprocess.STDOUT, env=env)
            else:
                output = subprocess.check_output([command] + args, cwd=cwd, env=env)
            if verbose:
                print(f"Command output: {output.decode()}")
        except subprocess.CalledProcessError as e:
            if verbose:
                print(f"Command failed: {e.output.decode()}")
            raise
        except Exception as e:
            if verbose:
                print(f"An error occurred: {e}")
            raise

