    """Validate storage root hierarchy.

    Returns:
        num_objects (int) - number of objects checked
        good_objects (int) - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    try:
        for key, value in self._storage.items():
            num_objects += 1
            if validate_objects:
                if check_digests and value['digest'] != self._calculate_digest(value['data']):
                    if show_warnings:
                        print(f"Warning: Digest mismatch for object {key}")
                    continue
                if self._validate_object(value['data']):
                    good_objects += 1
                else:
                    if show_warnings:
