def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    try:
        parts = list(map(int, version.split('.')))
        if len(parts) != 3:
            raise ValueError("Version must contain three parts: major, minor, and patch")

        # Increment the patch version
        parts[2] += 1

        # If the patch version is zero, reset it and increment the minor version
        if parts[2] == 0:
            parts[2] = 0
            parts[1] += 1

            # If the minor version is zero, reset it and increment the major version
            if parts[1] == 0:
                parts[0] += 1
                parts[1] = 0

        # Convert the parts back to a string and return
        return '.'.join(map(str, parts))
    except ValueError as e:
        print(f"Error: {e}")
        return version

