        if platform.system().lower() == 'windows':
            platform = 0
        else:
            platform = 1

    if platform == 0:
        # Windows/CMD escaping
        return re.findall(r'"([^"]*)"(?<!\\)|[^\s"]+', s)
    elif platform == 1:
        # POSIX escaping
        return re.findall(r'\\.[^\\]*(\\[^\\]*)*|"[^"]*"(?<!\\)|\S+', s)
    else:
        raise ValueError("Unsupported platform value")
