from pathlib import PosixPath

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not os.path.exists(archive_path):
        raise FileNotFoundError(f'The archive {archive_path} does not exist.')

    if isinstance(tmp_path, str):
        tmp_path = PosixPath(tmp_path)

    if not tmp_path.exists():
        raise NotADirectoryError(f'The temporary path {tmp_path} does not exist.')

    if not tmp_path.is_dir():
        raise NotADirectoryError(f'The temporary path {tmp_path} is not a directory.')

    if filename:
        extract_path = tmp_path / filename
    else:
        extract_path = tmp_path / os.path.basename(archive_path).split('.')[0]

    if extract_path.exists():
        raise FileExistsError(f'The extraction path {extract_path} already exists.')

    # Uncompress the archive
    if archive_path.endswith('.tar.gz'):
        subprocess.check_call(['tar', '-xzf', archive_path, '-C', str(tmp_path)])
    elif archive_path.endswith('.tar.bz2'):
        subprocess.check_call(['tar', '-xjf', archive_path, '-C', str(tmp_path)])
    elif archive_path.endswith('.zip'):
        subprocess.check_call(['unzip', archive_path, '-d', str(tmp_path)])
    else:
        raise ValueError(f'Unsupported archive type: {archive_path}')

    # Return a file repo url
    return str(extract_path)
