def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """

    errors = []

    if not tentative and not iface.providedBy(candidate):
        errors.append(zope.interface.Invalid("Candidate does not provide the interface"))

    # Check for necessary methods and their signatures
    for method, signature in iface.getTaggedValue "_"["necessary methods"].items():
        if not hasattr(candidate, method):
            errors.append(zope.interface.Invalid("%s does not define method %s" % (candidate, method)))
        else:
            method_obj = getattr(candidate, method)
            if not callable(method_obj):
                errors.append(zope.interface.Invalid("%s的方法 %s 不是可调用的" % (candidate, method)))
            else:
                argspec = inspect.getargspec(method_obj)
                required_args = len(argspec.args) - (1 if argspec.varargs else 0)
                if len(signature) != required_args:
                    errors.append(zope.interface.Invalid("%s 方法 %s 的参数不匹配" % (candidate, method)))
                for arg, type_ in zip(argspec.args, signature):
                    if not isinstance(getattr(candidate, method).__get__(candidate, candidate.__class__)(arg), type_):
                        errors.append(zope.interface.Invalid("%s 方法 %s 的参数 %s 类型不正确" % (candidate, method, arg)))
                if argspec.varargs:
                    if not all(isinstance(getattr(candidate, method).__get__(candidate, candidate.__class__)(arg), type_) for arg in argspec.varargs):
                        errors.append(zope.interface.Invalid("%s 方法 %s 的可变参数类型不正确" % (candidate, method)))

    # Check for necessary attributes
    for attribute, type_ in iface.getTaggedValue "_"["necessary attributes"].items():
        if not hasattr(candidate, attribute):
            errors.append(zope.interface.Invalid("%s 不定义属性 %s" % (candidate, attribute)))
        elif not isinstance(getattr(candidate, attribute), type_):
            errors.append(zope.interface.Invalid("%s 属性 %s 的类型不正确" % (candidate, attribute)))

    if errors:
        if len(errors) == 1:
            raise errors[0]
        else:
            raise zope.interface.Invalid("\n".join(str(error) for error in errors))
    return True

