import re
from dateutil.tz import tzoffset, tzutc

def isoparse(dt_str):
    """Parse an ISO-8601 datetime string into a :class:`datetime.datetime`.

    :param dt_str: A string containing only an ISO-8601 datetime string
    :return: Returns a :class:`datetime.datetime` representing the string
    """
    try:
        if isinstance(dt_str, bytes):
            dt_str = dt_str.decode('ascii')

        if dt_str.endswith('Z'):
            dt_str = dt_str[:-1]

        date_parts = dt_str.split('T')

        date = date_parts[0]
        time = date_parts[1] if len(date_parts) > 1 else ''

        year, month, day = map(int, date.split('-'))

        if len(time) > 0:
            time_parts = time.split('.')

            hour, minute, second = map(int, time_parts[0].split(':'))

            if len(time_parts) > 1:
                microsecond = int(round(float(time_parts[1]) * 1e6))
            else:
                microsecond = 0

            tz_parts = [part.strip('+-') for part in re.findall(r'[+-]\d\d:\d\d|\d\d\d\d|\d\d', time)]
            if tz_parts:
                tz_sign = 1 if tz_parts[0][0] == '+' else -1
                tz_hours = int(tz_parts[0][:2])
                tz_minutes = int(tz_parts[0][2:4])
                timezone_offset = timedelta(hours=tz_sign * tz_hours, minutes=tz_sign * tz_minutes)
            else:
                timezone_offset = timezone.utc

            return datetime(year, month, day, hour, minute, second, microsecond, tzinfo=timezone_offset)

        else:
            return datetime(year, month, day, tzinfo=timezone.utc)

    except (ValueError, TypeError, re.error) as e:
        raise ValueError(f"Invalid ISO-8601 datetime string: {dt_str}") from e
