def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if document.startswith('{') or document.startswith('['):
        return json.loads(document)
    else:
        root = ET.fromstring(document)
        hCard = {}
        for element in root:
            if element.tag.endswith("hCard"):
                for child in element:
                    if child.tag.endswith("FN"):
                        hCard['fn'] = child.text
                    elif child.tag.endswith("N"):
                        for subchild in child:
                            if subchild.tag.endswith("FamilyName"):
                                hCard['family-name'] = subchild.text
                            elif subchild.tag.endswith("GivenName"):
