def _evaluate_condition(self, condition, command_name, args):
    """Evaluate the condition for the given option.

    :param condition: the condition to evaluate
    :param command_name: the command name
    :param args: the received input arguments
    :return: bool, True if the condition is met, False otherwise
    """
    if not isinstance(condition, dict):
        raise ValueError("Invalid condition: %s" % condition)

    for key, value in condition.items():
        if key in args:
            if args[key] == value:
                return True
        elif key in os.environ:
            if os.environ[key] == value:
                return True
        else:
            raise ValueError("Condition key '%s' not found in arguments or environment" % key)

    return False
